import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        st.nextToken();
        int m = (int) st.nval;
        // length[x] is the run length stored at both ends of each occupied run.
        int[] length = new int[n + 2];
        for (int day = 1; day <= n; day++) {
            st.nextToken();
            int x = (int) st.nval;
            int left = length[x - 1], right = length[x + 1], total = left + right + 1;
            length[x] = total;
            length[x - left] = total;
            length[x + right] = total;
            if (total >= m) { System.out.println(day); return; }
        }
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n, m := nextInt(), nextInt()
	// length[x] is the run length stored at both ends of each occupied run.
	length := make([]int, n+2)
	for day := 1; day <= n; day++ {
		x := nextInt()
		left, right := length[x-1], length[x+1]
		total := left + right + 1
		length[x], length[x-left], length[x+right] = total, total, total
		if total >= m {
			fmt.Println(day)
			return
		}
	}
}
